 "content": "def transform(grid):
    """Repeat the shape tile, recolored by the marker in each row's first tile."""
    h, w = len(grid), len(grid[0])
    row_cuts = [r for r, row in enumerate(grid) if row[0] != 0 and all(v == row[0] for v in row)]
    col_cuts = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]

    def spans(size, cuts):
        out, start = [], 0
        for cut in cuts:
            if start < cut:
                out.append((start, cut))
            start = cut + 1
        if start < size:
            out.append((start, size))
        return out

    rows, cols = spans(h, row_cuts), spans(w, col_cuts)
    tile = lambda ri, ci: [(r, c) for r in range(*rows[ri]) for c in range(*cols[ci])]

    # Each first-column tile contains that tile-row's color marker.
    row_colors = []
    for ri in range(len(rows)):
        cells = [grid[r][c] for r, c in tile(ri, 0) if grid[r][c] != 0]
        if not cells:
            row_colors.append(0)
        else:
            row_colors.append(max(set(cells), key=cells.count))

    source_colors = set(row_colors)
    shape = None
    for ri in range(len(rows)):
        for ci in range(1, len(cols)):
            cells = tile(ri, ci)
            vals = {grid[r][c] for r, c in cells if grid[r][c] != 0}
            if vals and not vals.issubset(source_colors):
                r0, c0 = rows[ri][0], cols[ci][0]
                shape = [(r-r0, c-c0) for r, c in cells if grid[r][c] != 0]
                break
        if shape is not None:
            break
    if shape is None:
        raise ValueError('No distinct template shape found')

    result = [[0 for _ in range(w)] for _ in range(h)]
    # Preserve the grid's row and column separators.
    for r in row_cuts:
        result[r] = list(grid[r])
    for c in col_cuts:
        for r in range(h):
            result[r][c] = grid[r][c]
    for ri, color in enumerate(row_colors):
        if color == 0:
            continue
        for ci in range(len(cols)):
            r0, c0 = rows[ri][0], cols[ci][0]
            for dr, dc in shape:
                result[r0 + dr][c0 + dc] = color
    return result
